const tree = $json.tree || [];
const pyFiles = tree.filter((t) => t.type === 'blob' && t.path.endsWith('.py')).slice(0, 100);
return pyFiles.map((f) => ({ json: { path: f.path, blob_sha: f.sha } }));

// Regex call-site search with a docstring/comment skip -- see the header
// comment on this file for why that skip exists. Not a real parser: still
// possible to fool with unusual formatting. Good enough for the MVP's
// stated 'import-level, not full call-graph' scope (PRD Section 2/6.2).
const symbols = $('When called as a tool').first().json.symbols || [];
const results = [];

for (const item of $input.all()) {
  const filePath = item.json.path;
  const content = typeof item.json === 'string' ? item.json : (item.json.data || item.json.body || '');
  const lines = String(content).split('\n');
  let inDocstring = false;

  lines.forEach((rawLine, i) => {
    const trimmed = rawLine.trim();
    const wasInDocstring = inDocstring;
    const tripleQuoteCount = (trimmed.match(/"""|'''/g) || []).length;
    const isOneLineDocstring = tripleQuoteCount >= 2 && (trimmed.startsWith('"""') || trimmed.startsWith("'''"));
    if (tripleQuoteCount % 2 === 1) inDocstring = !inDocstring;
    if (wasInDocstring || isOneLineDocstring || trimmed.startsWith('#')) return;

    for (const sym of symbols) {
      const shortName = sym.split('.').pop();
      const escaped = shortName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const re = new RegExp(`\\b${escaped}\\s*\\(`);
      if (re.test(rawLine)) {
        results.push({ file: filePath, line: i + 1, symbol: sym, snippet: trimmed });
      }
    }
  });
}

return [{ json: { symbols, matches: results } }];
